const [successPaymentData, setSuccessPaymentData] = useState<any>(null); // Store full payment object

// ... (existing imports)
import { PdfGenerator } from "@/lib/pdfGenerator";

// ... (start of component)

// Polling Effect
useEffect(() => {
    let interval: NodeJS.Timeout;

    if (step === "PROCESSING" && currentPaymentId) {
        interval = setInterval(async () => {
            try {
                const res = await fetch(`/api/payments/status/${currentPaymentId}`);
                if (res.ok) {
                    const data = await res.json();
                    if (data.status === "SUCCESS") {
                        setSuccessPaymentData(data); // Save full payment data
                        setStep("SUCCESS");
                        onSuccess();
                        clearInterval(interval);
                    } else if (data.status === "FAILED") {
                        setError("Payment failed or was rejected.");
                        // Optional: setStep("DETAILS") to retry
                        clearInterval(interval);
                    }
                }
            } catch (error) {
                console.error("Polling error:", error);
            }
        }, 3000); // Poll every 3 seconds
    }

    return () => clearInterval(interval);
}, [step, currentPaymentId, onSuccess]);

const handleDownloadReceipt = () => {
    if (invoice && successPaymentData) {
        // We need to match the interface expected by PdfGenerator
        // invoice prop has { id, amount, currency }
        // successPaymentData has { id, amount, provider, status, transactionId, createdAt, phoneNumber }

        // We need to cast or ensure data is sufficient
        // The Invoice interface in PdfGenerator expects: id, amount, currency, status, issuedAt
        // Our prop is limited. We might need to enrich it or accept partial.
        // Let's coerce for now since PdfGenerator handles it safely mostly, 
        // but we lack 'issuedAt' and 'status' in the prop.
        // Actually, if payment is success, invoice is PAID.

        const fullInvoice = {
            ...invoice,
            status: "PAID",
            issuedAt: new Date().toISOString(), // Fallback if not provided
        };

        PdfGenerator.generateReceipt(fullInvoice as any, successPaymentData);
    }
};

// ... (inside render)

<button
    onClick={handleDownloadReceipt}
    className="w-full py-3 text-sm font-semibold text-slate-600 hover:text-slate-900 transition-colors"
>
    Download Receipt
</button>